SET NAMES utf8mb4;

CREATE TABLE biomes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    grade TINYINT NOT NULL,
    title VARCHAR(100) NOT NULL,
    description TEXT,
    climate_modifiers JSON NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE events (
    id INT AUTO_INCREMENT PRIMARY KEY,
    biome_id INT NOT NULL,
    node_type ENUM('normal', 'elite', 'boss') DEFAULT 'normal',
    title VARCHAR(150) NOT NULL,
    story_text TEXT NOT NULL,
    question_text TEXT NOT NULL,
    options JSON NOT NULL,
    correct_index TINYINT NOT NULL,
    reward_xp INT DEFAULT 25,
    penalty_supplies INT DEFAULT 15,
    explanation TEXT NOT NULL,
    FOREIGN KEY (biome_id) REFERENCES biomes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE runs (
    id VARCHAR(36) PRIMARY KEY,
    student_name VARCHAR(100) NOT NULL,
    grade TINYINT NOT NULL,
    biome_id INT NOT NULL,
    seed INT NOT NULL,
    supplies INT DEFAULT 100,
    equipment INT DEFAULT 100,
    score INT DEFAULT 0,
    current_step INT DEFAULT 0,
    pending_event_id INT NULL,
    map_graph JSON NOT NULL,
    inventory JSON NOT NULL,
    status ENUM('active', 'victory', 'defeat') DEFAULT 'active',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (biome_id) REFERENCES biomes(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE run_logs (
    id INT AUTO_INCREMENT PRIMARY KEY,
    run_id VARCHAR(36) NOT NULL,
    event_id INT NOT NULL,
    chosen_index TINYINT NOT NULL,
    is_correct BOOLEAN NOT NULL,
    answered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (run_id) REFERENCES runs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO biomes (grade, title, description, climate_modifiers) VALUES
(7, 'Перетин Анд і Амазонії', 'Висотний пояс Анд та вологі ліси.', '{"humidity": "extreme", "base_supply_cost": 5}'),
(8, 'Український щит та Степ', 'Геологічна будова та південь України.', '{"drought_risk": "high", "base_supply_cost": 4}');

INSERT INTO events (biome_id, node_type, title, story_text, question_text, options, correct_index, reward_xp, penalty_supplies, explanation) VALUES
(1, 'normal', 'Східні схили Анд', 'Біля підніжжя (500 м) температура +24°C. Ви піднімаєтесь на перевал 4500 м.', 'Яка приблизна температура на перевалі за зниження на 6°C на кожен кілометр висоти?', '["+12°C", "0°C", "-12°C"]', 1, 30, 20, 'Різниця висот становить 4500 − 500 = 4000 м. За заданим градієнтом температура знизиться на 4 × 6 = 24°C: +24 − 24 = 0°C.'),
(1, 'normal', 'Витоки великої річки', 'Експедиція спускається з Анд до басейну Амазонки.', 'До якого океану несе води Амазонка?', '["Тихого", "Індійського", "Атлантичного"]', 2, 30, 15, 'Амазонка тече переважно із заходу на схід і впадає в Атлантичний океан. Анди утворюють західний вододіл її басейну.'),
(1, 'normal', 'Вологий ліс', 'Навколо табору росте багатоярусний вічнозелений ліс.', 'Які умови сприяють утворенню вологих екваторіальних лісів Амазонії?', '["Високі температури й рясні опади протягом року", "Морози й коротке літо", "Спека та майже повна відсутність опадів"]', 0, 25, 15, 'В екваторіальній частині Амазонії весь рік тепло й волого. Ці умови підтримують розвиток багатоярусних вічнозелених лісів.'),
(1, 'normal', 'Зміна рослинності', 'Під час підйому в Андах ліси змінюються високогірними луками.', 'Як називають закономірну зміну природних комплексів із висотою?', '["Широтна зональність", "Висотна поясність", "Рух літосферних плит"]', 1, 30, 15, 'Висотна поясність — це зміна природних комплексів у горах із висотою, передусім через зниження температури та зміну зволоження.'),
(1, 'normal', 'Річкова переправа', 'Мандрівники шукають притоку Амазонки на карті.', 'Яка з цих річок належить до басейну Амазонки?', '["Парана", "Оріноко", "Мадейра"]', 2, 25, 15, 'Мадейра — велика права притока Амазонки. Парана й Оріноко належать до інших річкових басейнів Південної Америки.'),
(1, 'normal', 'Вологе повітря', 'Вітри приносять до Амазонської низовини вологу з океану.', 'Який океан є головним джерелом цієї вологи зі сходу?', '["Атлантичний", "Тихий", "Північний Льодовитий"]', 0, 25, 15, 'Пасати переносять вологе повітря з Атлантичного океану вглиб материка. Анди перешкоджають його подальшому руху на захід.'),
(1, 'elite', 'Народження Анд', 'На маршруті видно вулканічні вершини й сліди землетрусів.', 'Який процес утворює Анди на заході Південної Америки?', '["Розходження Африканської та Південноамериканської плит", "Занурення плити Наска під Південноамериканську плиту", "Лише руйнування гір річками"]', 1, 50, 20, 'Океанічна плита Наска занурюється під Південноамериканську плиту. Зближення плит спричиняє горотворення, землетруси та вулканізм в Андах.'),
(1, 'boss', 'Бар’єр над Амазонією', 'Вологе повітря з Амазонії піднімається східними схилами Анд.', 'Чому під час підйому повітря на цих схилах часто випадають опади?', '["Повітря нагрівається, і водяна пара зникає", "Гори створюють морські течії", "Повітря охолоджується, і водяна пара конденсується"]', 2, 80, 25, 'Піднімаючись схилом, вологе повітря розширюється й охолоджується. Водяна пара конденсується, утворюючи хмари та орографічні опади.'),
(2, 'normal', 'Виходи кристалічних порід', 'У долині в межах Українського щита ви натрапили на виходи гранітів.', 'Яка тектонічна структура лежить в основі цієї території?', '["Западина", "Кристалічний щит", "Молода складчаста область"]', 1, 30, 15, 'Український щит — піднята ділянка давнього кристалічного фундаменту Східноєвропейської платформи, де породи фундаменту виходять на поверхню або лежать близько до неї.'),
(2, 'normal', 'Давній фундамент', 'Геологічна карта показує Український щит у межах великої платформи.', 'Частиною якої платформи є Український щит?', '["Східноєвропейської", "Західносибірської", "Південноамериканської"]', 0, 30, 15, 'Український щит належить до Східноєвропейської платформи. Його фундамент складений переважно докембрійськими кристалічними породами.'),
(2, 'normal', 'Гранітний берег', 'На березі річки ви досліджуєте зразок граніту.', 'До якої групи порід за походженням належить граніт?', '["Осадових", "Метаморфічних", "Магматичних"]', 2, 25, 15, 'Граніт — магматична глибинна порода. Він утворюється внаслідок повільного охолодження й кристалізації магми в земній корі.'),
(2, 'normal', 'Степовий ґрунт', 'Під травами степу видно темний гумусовий горизонт.', 'Які ґрунти характерні для більшої частини степової зони України?', '["Підзолисті", "Чорноземи", "Тундрово-глейові"]', 1, 30, 15, 'У степовій зоні України переважають чорноземи, сформовані під трав’янистою рослинністю. У найсухішій південній частині поширені також каштанові ґрунти.'),
(2, 'normal', 'Брак води', 'Улітку на степовому маршруті тривалий час немає дощу.', 'Яка риса клімату зумовлює часті посухи в степу України?', '["Випаровуваність перевищує кількість опадів", "Опади значно перевищують випаровуваність", "Цілорічні сильні морози"]', 0, 25, 15, 'Для степу характерне недостатнє зволоження: потенційне випаровування перевищує кількість опадів. Спекотне літо й суховії посилюють ризик посух.'),
(2, 'normal', 'Рудний маршрут', 'Експедиція наближається до Криворізького басейну в межах Українського щита.', 'На видобутку якої корисної копалини спеціалізується цей басейн?', '["Кам’яного вугілля", "Кам’яної солі", "Залізної руди"]', 2, 30, 15, 'Криворізький залізорудний басейн пов’язаний із давніми породами Українського щита. Він є одним із головних районів видобутку залізних руд в Україні.'),
(2, 'elite', 'Захист степового поля', 'Сильний вітер зносить сухий верхній шар ґрунту з розораного поля.', 'Який захід допомагає зменшити вітрову ерозію?', '["Знищення рослинного покриву", "Створення полезахисних лісосмуг", "Розширення суцільної оранки без захисних насаджень"]', 1, 50, 20, 'Полезахисні лісосмуги зменшують швидкість вітру біля поверхні, затримують сніг і допомагають захищати ґрунт від видування.'),
(2, 'boss', 'Щит під степом', 'На півдні Українського щита поруч із виходами гранітів простягається степ.', 'Чому тектонічний щит і степова природна зона можуть збігатися на одній території?', '["Щит визначає геологічну будову, а природна зона залежить насамперед від клімату", "Будь-який щит обов’язково вкритий лише степом", "Природні зони визначаються тільки віком гірських порід"]', 0, 80, 25, 'Тектонічні структури характеризують будову земної кори, а природні зони — поєднання клімату, ґрунтів і живих організмів. Тому частина Українського щита лежить у степовій зоні, а інші його частини — в інших природних зонах.');
